function toast(message){const n=document.createElement('div');n.className='toast';n.textContent=message;$('#toasts').append(n);setTimeout(()=>n.remove(),6500);}
async function api(path,body){if(nativeMode)return nativeApi(path,body);const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-MXL-Token':token},body:body===undefined?undefined:JSON.stringify(body)});let j;try{j=await r.json();}catch{throw new Error('Management service returned an invalid response');}if(!r.ok)throw new Error(j.error||'Request failed');return j;}
const pretty=v=>JSON.stringify(v,null,2);
const details=(v,label='Show device response')=>`<details class="live-details"><summary>${esc(label)}</summary><pre class="code">${esc(pretty(v))}</pre></details>`;
const genericTable=d=>{const rows=flattenRows(d);if(!rows.length)return empty('No entries','The switch returned an empty table.');const keys=[...new Set(rows.flatMap(x=>Object.keys(x)))];return table(keys.map(esc),rows.map(r=>row(keys.map(k=>esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k]??'—')))));};
function reading(key,titleText,render=genericTable){if(state.errors[key])return card(titleText,`<p class="live-error">${esc(state.errors[key])}</p>`);if(!state.cache[key])return card(titleText,'<p class="muted">Refresh this page to read the switch.</p>');return card(titleText,render(data(key))+`<p class="live-status">Read from switch · ${esc(new Date(state.cache[key].observed_at).toLocaleTimeString())}${state.cache[key].stream_complete===false?' · partial event stream':''}</p>`+details(data(key)),pill('Live','live'),'read-card');}
const num=(key,label,value,min,max,hint='')=>({key,label,value,type:'number',min,max,hint});
const txt=(key,label,value='',max=64,hint='')=>({key,label,value,type:'text',max,hint});
const yes=(key,label,value=false,hint='')=>({key,label,value:!!value,type:'boolean',hint});
const choose=(key,label,options,value)=>({key,label,options,value,type:'select'});
const port=(key='port',label='Port',value=1)=>choose(key,label,PORTS.map(p=>[p,`${p}${p>8?' · SFP+':''}`]),value);
const portSet=(key='ports',label='Ports',value=PORTS)=>({key,label,value,type:'ports'});
const forms=new Map();
function form(action,titleText,fields,note='',label='Apply to switch'){
 const id='form-'+forms.size;forms.set(id,{action,fields});
 let controls=fields.map(f=>f.type==='boolean'?check(f.label,f.key,f.value,f.hint):f.type==='ports'?`<div class="field"><label>${esc(f.label)}</label>${portChecks(f.key,f.value)}</div>`:f.type==='select'?selectField(f.label,f.key,f.options,f.value):field(f.label,f.key,f.value,f.type,f.hint,f.type==='number'?`min="${f.min}" max="${f.max}" required`:`maxlength="${f.max}" ${f.required?'required':''}`)).join('');
 controls=controls.replace(/\b(id|for)="([^"]+)"/g,(_,attr,value)=>`${attr}="${id}-${value}"`);
 return card(titleText,`<form class="live-form" data-live-form="${id}"><div class="form-grid">${controls}</div>${note?`<p class="note">${esc(note)}</p>`:''}<div class="formactions"><button type="submit" class="ctl pri" ${state.busy?'disabled':''}>${esc(label)}</button></div><p class="form-error" role="alert"></p></form>`);
}
function scalarRows(d){return kv(Object.entries(d||{}).filter(([,v])=>v===null||typeof v!=='object'));}
function portTable(){const p=obj('ports');return table(['Port','State','Configured','Link','Flow control','EEE'],PORTS.map(i=>{const x=p['Port_'+i]||{};return row([String(i),esc(x.Port_Status),esc(x.Spd_Duplex_Cfg),pill(x.Spd_Duplex_Actual||'Unknown',String(x.Spd_Duplex_Actual).includes('Down')?'':'good'),esc(x.Flow_Ctrl_Cfg),esc(x.EEE_Status)]);}));}
function dashboard(){const s=obj('status'),p=obj('ports');const up=PORTS.filter(i=>p['Port_'+i]?.Spd_Duplex_Actual&&!p['Port_'+i].Spd_Duplex_Actual.includes('Down')).length;return head(title(),'Live status from your switch. Settings are applied only when you submit a form.')+`<div class="metrics">${metric('Ports linked',`${up} / 10`,'8 copper · 2 SFP+')}${metric('Temperature',s.temperature??'—','Device sensor','°C')}${metric('Firmware',s.fw_ver??'—','Reported by switch')}${metric('LLDP enabled',PORTS.filter(p=>obj('lldp')['Port_'+p]).length+' / 10','Native LLDP state')}</div>`+`<div class="live-grid">${card('Switch identity',kv([['Name',title()],['Location',inventoryValue('location')||'Not set'],['MAC',s.sys_macaddr],['Management',s.sys_ipv4],['Hardware',s.hw_ver],['OEM model',s.des]]))}${card('Getting things done',`<p>Configure ports, VLANs, spanning tree and discovery from the navigation. Refresh reads current state; Save configuration writes running settings to startup.</p><p class="note">${nativeMode?(state.inventory._persistent?'Location and contact are stored on the switch.':'Location and contact are saved in this browser for this switch until native storage is connected.'):'Location and contact are stored by this management service until a native setter is available.'}</p>`)}</div>`+reading('ports','Front panel',portTable);}
function statistics(){return head('Port statistics','Measured packet counts. Packet rates use consecutive live samples; no traffic is generated.',btn('Clear counters','clear-statistics','','danger'))+reading('statistics','Packet counters',d=>table(['Port','Link','TX good','RX good','TX bad','RX bad','TX pkt/s','RX pkt/s'],PORTS.map(i=>{const p=d['Port_'+i]||{},r=state.rates[i];return row([String(i),esc(p.Link_Status),number(p.TxGoodPkt),number(p.RxGoodPkt),number(p.TxBadPkt),number(p.RxBadPkt),r?esc(r.tx.toFixed(1)):'—',r?esc(r.rx.toFixed(1)):'—']);})));}
function portsPage(){return head('Ports','Configure copper and SFP+ ports using the V2 port map.')+reading('ports','Current configuration',portTable)+jumboFrames()+form('ports','Configure selected ports',[portSet('ports','Ports',[]),yes('enabled','Enabled',true),choose('speed','Speed / duplex',['Auto','10Mbps Half','10Mbps Full','100Mbps Half','100Mbps Full','1000Mbps Full','2500Mbps Full','10Gbps Full'],'Auto'),yes('flow','Flow control',true)],'Changing the management uplink can disconnect this session. SFP mode remains the OEM default. Module identity and diagnostics are on the SFP modules page.');}
