function lag(){
 let groups=[],error='';try{groups=lagGroups(data('lag'));}catch(e){error=e.message;}
 const config=obj('lag'),fields=[{key:'priority',type:'number'},...PORTS.flatMap(p=>['mode','group','priority','timeout'].map(key=>({key:key+'_'+p,type:'number'})))];
 forms.set('lag-config',{action:'lag',fields});
 const summary=card('Configured groups',error?`<p class="live-error">${esc(error)}</p>`:groups.length?table(['Group','Mode','Member ports'],groups.map(g=>row([esc(g.label),g.mode===2?'LACP':'Static',g.ports.map(p=>portChip(p)).join(' ')])))+'<p class="note">Set VLAN membership and PVIDs for the group on VLANs & PVID.</p>':empty('No LAGs configured','Assign at least two ports to the same group below.'));
 const editor=card('Configure aggregation',`<form class="live-form" data-live-form="lag-config">${field('System priority','priority',config.system_priority??32768,'number','LACP system priority','min="0" max="65535" required')}<div class="scrollx">${table(['Port','Mode','Group','Port priority','LACP timeout'],PORTS.map(p=>{
  const x=config['Port_'+p]||{};
  return row([portChip(p),select('mode_'+p,[[0,'Independent'],[1,'Static LAG'],[2,'LACP']],x['portTypeId_'+p]??0,`aria-label="Port ${p} aggregation mode"`),`<input class="in sm" name="group_${p}" type="number" min="0" max="15" required value="${esc(x['Port_'+p+'_grpInd']??0)}" aria-label="Port ${p} LAG group">`,`<input class="in sm" name="priority_${p}" type="number" min="0" max="65535" required value="${esc(x['portPriorityId_'+p]??128)}" aria-label="Port ${p} LACP priority">`,select('timeout_'+p,[[0,'Short'],[1,'Long']],x['lacpTimeoutId_'+p]??0,`aria-label="Port ${p} LACP timeout"`)]);
 }))}</div><p class="note">Choose the same group and mode for at least two ports. Group IDs are 0–15. Keep member VLANs, PVIDs and link settings consistent, and configure the peer to match. Applying aggregation can interrupt traffic. Save configuration to retain changes.</p><div class="formactions"><button type="submit" class="ctl pri">Apply aggregation</button></div><p class="form-error" role="alert"></p></form>`);
 return head('LAGs & LACP','Combine physical ports into static or negotiated link aggregation groups.')+summary+editor+`<details class="live-details"><summary>Negotiated state and diagnostic responses</summary>${reading('lag-status','Negotiated state')}${details(config,'Raw aggregation configuration')}</details>`;
}
function mirroring(){const d=obj('mirror');return head('Port mirroring','Copy selected ingress and egress traffic to one monitor port.')+reading('mirror','Current mirroring')+form('mirror','Configure mirror',[choose('destination','Monitor port',[[0,'Disabled'],...PORTS.map(p=>[p,'Port '+p])],d.MonitoringPortId||0),portSet('ports','Source ports',PORTS.filter(p=>on(d['Port_'+p]?.Ingress_Status)||on(d['Port_'+p]?.Egress_Status))),yes('ingress','Mirror ingress',PORTS.some(p=>on(d['Port_'+p]?.Ingress_Status))),yes('egress','Mirror egress',PORTS.some(p=>on(d['Port_'+p]?.Egress_Status)))],'The native web API uses one common direction selection for all selected sources.');}
