 if(qosTab==='cos')body+=reading('qos-cos','802.1p / CoS map')+form('cos','Set CoS traffic classes',Array.from({length:16},(_,i)=>num('tc_'+i,'Index '+i,Number(obj('qos-cos')['Idx_'+i]?.Mapped_Tc)||0,0,7)),'All 16 native mapping entries are submitted together.');
